public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] dist = new int[n];
    Arrays.fill(dist, Integer.MAX_VALUE);
    dist[0] = 0;
    PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
    pq.add(new int[]{0, 0});
    while (!pq.isEmpty()) {
        int[] curr = pq.poll();
        int node = curr[1];
        if (hasApple[node]) {
            return dist[node];
        }
        for (int[] edge : edges) {
            int neighbor = edge[node];
            int newDist = dist[node] + 1;
            if (newDist < dist[neighbor]) {
                dist[neighbor] = newDist;
                pq.add(new int[]{newDist, neighbor});
            }
        }
    }
    return 0;
}

