public boolean splitArraySameAverage(int[] nums) {
    if (nums.length % 2 == 1) return false;
    int sum = 0, count = 0;
    for (int num : nums) {
        sum += num;
        count++;
    }
    double avg = sum / (double) count;
    double leftSum = 0, rightSum = 0;
    int leftCount = 0, rightCount = nums.length / 2;
    for (int i = 0; i < nums.length / 2; i++) {
        leftSum += nums[i];
        leftCount++;
        rightSum += nums[i + nums.length / 2];
        rightCount++;
        if (leftSum == rightSum) return true;
    }
    return Math.abs(leftSum - rightSum) / Math.min(leftCount, rightCount) < avg;
}

