public static int findSmallestInteger(int n) {
    int smallest = -1;
    int[] digits = new int[10];
    int i;

    // count the frequency of each digit
    for (i = 0; i < 10; i++) {
        digits[i] = 0;
    }
    while (n > 0) {
        digits[n % 10]++;
        n /= 10;
    }

    // check if the smallest number is possible
    boolean possible = true;
    for (i = 0; i < 10; i++) {
        if (digits[i] == 0) {
            possible = false;
            break;
        }
    }
    if (!possible) {
        return -1;
    }

    // generate all possible combinations of digits
    for (i = 0; i < 10; i++) {
        if (digits[i] > 0) {
            smallest = smallest * 10 + i;
            digits[i]--;
        }
    }

    return smallest;
}

