    Arrays.fill(digits, 0);
    int smallest = -1;

    while (n > 0) {
        digits[n % 10]++;
        n /= 10;
    }

    for (int i = 9; i >= 0; i--) {
        if (digits[i] > 0) {
            smallest = i;
            break;
        }
    }

    if (smallest == -1) {
        return -1;
    }

    while (smallest > 0) {
        smallest *= 10;
        smallest += digits[smallest / 10];
        digits[smallest / 10] = 0;
    }

    return smallest;
}

