public static List<Integer> lexicalOrder(int n) {
    List<Integer> lexicalList = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        lexicalList.add(i);
    }
    for (int i = 10; i <= n; i++) {
        int digit = i % 10;
        int index = i / 10 - 1;
        if (digit > lexicalList.get(index)) {
            lexicalList.add(i);
        } else {
            lexicalList.add(index + 1, i);
        }
    }
    return lexicalList;
}

