public static int minPerfectSquareSum(int n) {
    int count = 0;
    int sum = 0;
    while (sum < n) {
        int nextSquare = (int) Math.pow(count + 1, 2);
        if (sum + nextSquare > n) {
            break;
        }
        count++;
        sum += nextSquare;
    }
    return count;
}

